1. First, make sure you have Node.js and npm installed on your system. You can download Node.js from https://nodejs.org/.

2. Create a new directory for your project and navigate to it in your terminal or command prompt.

3. Initialize a new npm package by running:

```bash
npm init -y
```

4. Install Electron as a dev dependency:

```bash
npm install electron --save-dev
```

5. Create a new file named `main.js` in your project directory and add the following code:

```javascript
// main.js

const { app, BrowserWindow } = require('electron');

function createWindow() {
  const win = new BrowserWindow({
    width: 800,
    height: 600,
  });

  win.loadFile('index.html');
}

app.whenReady().then(createWindow);

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

app.on('activate', () => {
  if (BrowserWindow.getAllWindows().length === 0) {
    createWindow();
  }
});
```

6. Create a new file named `index.html` in your project directory and add the following code:

```html
